import java.util.*;

class Solution {
  private final Map<String, Integer> memo = new HashMap<>();

  public int findMinStep(String board, String hand) {
    int[] count = new int[26];
    for (char c : hand.toCharArray()) count[c - 'A']++;
    int result = dfs(board, count);
    return result == Integer.MAX_VALUE ? -1 : result;
  }

  private int dfs(String board, int[] hand) {
    board = shrink(board);
    if (board.isEmpty()) return 0;
    String key = board + "," + Arrays.toString(hand);
    if (memo.containsKey(key)) return memo.get(key);
    int best = Integer.MAX_VALUE;
    for (int i = 0; i < board.length(); ) {
      int j = i;
      while (j < board.length() && board.charAt(j) == board.charAt(i)) j++;
      int need = 3 - (j - i);
      int color = board.charAt(i) - 'A';
      if (hand[color] >= need) {
        hand[color] -= need;
        int rest = dfs(board.substring(0, i) + board.substring(j), hand);
        if (rest != Integer.MAX_VALUE) best = Math.min(best, rest + need);
        hand[color] += need;
      }
      i = j;
    }
    memo.put(key, best);
    return best;
  }

  private String shrink(String s) {
    for (int i = 0; i < s.length(); ) {
      int j = i;
      while (j < s.length() && s.charAt(j) == s.charAt(i)) j++;
      if (j - i >= 3) return shrink(s.substring(0, i) + s.substring(j));
      i = j;
    }
    return s;
  }
}
